-- Run once against a NEW, dedicated MySQL 8 database before using the production profile.
-- Employee IDs are generated by MySQL. No original LMS database is modified automatically.
CREATE TABLE IF NOT EXISTS employee (
  emp_id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  emp_name VARCHAR(100) NOT NULL,
  email VARCHAR(100) NOT NULL,
  phone_number VARCHAR(10) NOT NULL,
  designation VARCHAR(50) NOT NULL,
  dept_id INT NULL,
  manager_id INT NULL,
  gender VARCHAR(10) NOT NULL,
  address VARCHAR(200) NOT NULL,
  CONSTRAINT uk_employee_email UNIQUE (email),
  CONSTRAINT uk_employee_phone UNIQUE (phone_number),
  CONSTRAINT fk_employee_manager FOREIGN KEY (manager_id) REFERENCES employee(emp_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- Username is the normalized employee email; the initial administrator may lack a profile.
CREATE TABLE IF NOT EXISTS login (
  username VARCHAR(100) NOT NULL PRIMARY KEY,
  password VARCHAR(255) NOT NULL,
  role ENUM('ADMIN','EMPLOYEE','HR','MANAGER') NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Outbox has no FK to employee because deletion events must survive profile deletion.
CREATE TABLE IF NOT EXISTS employee_event (
 event_id VARCHAR(36) NOT NULL PRIMARY KEY,
 employee_id INT NULL,
 event_type VARCHAR(20) NOT NULL,
 created_at TIMESTAMP(6) NOT NULL,
 published BIT NOT NULL DEFAULT 0,
 INDEX ix_employee_event_pending (published,created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
